@extends('layouts.app') @section('title',$member->exists?'Edit member':'Add member') @section('heading',$member->exists?'Edit member':'Register a member') @section('content')<div class="panel form-panel"><form method="POST" action="{{ $member->exists?route('members.update',$member):route('members.store') }}">@csrf @if($member->exists)@method('PUT')@endif<div class="form-grid"><div class="field full"><label>Link student account (optional)</label><select name="user_id"><option value="">No linked account</option>@foreach($users as $u)<option value="{{ $u->id }}" @selected(old('user_id',$member->user_id)==$u->id)>{{ $u->name }} · {{ $u->email }}</option>@endforeach</select></div><div class="field"><label>First name</label><input name="first_name" value="{{ old('first_name',$member->first_name) }}" required></div><div class="field"><label>Last name</label><input name="last_name" value="{{ old('last_name',$member->last_name) }}" required></div><div class="field"><label>Email</label><input type="email" name="email" value="{{ old('email',$member->email) }}" required></div><div class="field"><label>Phone</label><input name="phone" value="{{ old('phone',$member->phone) }}"></div><div class="field full"><label>Address</label><input id="address" name="address" value="{{ old('address',$member->address) }}"><small class="muted">Choose a location on the map below if Maps is configured.</small></div><div class="field"><label>Membership category</label><select name="membership_category_id" required><option value="">Select category</option>@foreach($categories as $c)<option value="{{ $c->id }}" @selected(old('membership_category_id',$member->membership_category_id)==$c->id)>{{ $c->name }}</option>@endforeach</select></div><div class="field"><label>Membership level</label><select name="membership_level_id" required><option value="">Select level</option>@foreach($levels as $l)<option value="{{ $l->id }}" @selected(old('membership_level_id',$member->membership_level_id)==$l->id)>{{ $l->name }} — ₱{{ number_format($l->fee,2) }}</option>@endforeach</select></div><input type="hidden" name="latitude" id="latitude" value="{{ old('latitude',$member->latitude) }}"><input type="hidden" name="longitude" id="longitude" value="{{ old('longitude',$member->longitude) }}"></div>@if(config('services.google_maps.browser_key'))<div id="member-map" class="map-box"></div>@else<div class="map-note">Google Maps will be available after configuring GOOGLE_MAPS_BROWSER_KEY in your .env file.</div>@endif<div class="form-actions"><a href="{{ route('members.index') }}" class="btn-outline">Cancel</a><button class="btn-primary">{{ $member->exists?'Save changes':'Create member' }}</button></div></form></div>@endsection @if(config('services.google_maps.browser_key'))@push('scripts')<script src="https://maps.googleapis.com/maps/api/js?key={{ config('services.google_maps.browser_key') }}&libraries=places"></script><script>const initial={lat:parseFloat(document.getElementById('latitude').value)||14.5995,lng:parseFloat(document.getElementById('longitude').value)||120.9842};const map=new google.maps.Map(document.getElementById('member-map'),{center:initial,zoom:12});const marker=new google.maps.Marker({position:initial,map,draggable:true});const setPoint=p=>{document.getElementById('latitude').value=p.lat();document.getElementById('longitude').value=p.lng()};map.addListener('click',e=>{marker.setPosition(e.latLng);setPoint(e.latLng)});marker.addListener('dragend',e=>setPoint(e.latLng));const input=document.getElementById('address');const autocomplete=new google.maps.places.Autocomplete(input);autocomplete.addListener('place_changed',()=>{const p=autocomplete.getPlace();if(p.geometry){map.setCenter(p.geometry.location);marker.setPosition(p.geometry.location);setPoint(p.geometry.location)}});</script>@endpush @endif
